// Smart pointer owns resource
std::unique_ptr<Resource> safe_ptr(new Resource());

// Release ownership, get raw pointer
Resource* raw_ptr = safe_ptr.release();

// safe_ptr is now nullptr, no longer owns the memory
if (safe_ptr == nullptr) {
    // Ownership transferred successfully
}

